from lib89 import *
def B(ch,tn,*a,**k): build('maths',ch,tn,*a,**k)
B(5,'Circles and chords','Circles, chords and the circumcircle','The round pond',
 "A village wants a round pond with a well exactly at its centre. How can they find the centre from just a few points on the edge? Circle geometry gives the answer.",
 [("A circle is the set of all points in a plane at a fixed distance, the radius, from a fixed point called the centre.","circle, radius, centre"),
  ("A circle has reflection symmetry across any diameter and rotational symmetry about its centre through any angle.","symmetry"),
  ("Infinitely many circles pass through two given points, and their centres lie on the perpendicular bisector of the segment joining the two points.","perpendicular bisector"),
  ("Three points that are not on a straight line lie on exactly one circle, the circumcircle. Its centre, the circumcentre, is where the perpendicular bisectors meet.","circumcircle and circumcentre"),
  ("Equal chords subtend equal angles at the centre, and the converse is also true.","equal chords, equal angles"),
  ("A line from the centre to the midpoint of a chord is perpendicular to the chord, and a perpendicular from the centre to a chord bisects it.","centre to midpoint is perpendicular"),
  ("Equal chords are equally distant from the centre. Of two unequal chords, the longer one is closer to the centre.","longer chord, closer to centre"),
  ("The angle subtended by an arc at the centre is double the angle subtended at a point on the remaining part of the circle.","angle at centre = 2 x angle at circumference")],
 ("A chord AB of length 16 cm is 6 cm from the centre of a circle. Find the radius.",[("The perpendicular from the centre bisects the chord, so half the chord is 8 cm.","Use the bisecting property."),("Radius squared = 8^2 + 6^2 = 100.","Right triangle: half chord, distance and radius."),("Radius = 10 cm.","Take the square root.")]),
 ("How can you find the centre of a circle through three given points?",["Draw perpendicular bisectors of two chords","Their meeting point is the circumcentre","Distance to any point is the radius"],["Thinking three collinear points define a circle"]),
 ["All points of a circle are at the same distance from the centre.","A unique circle passes through three non-collinear points.","The perpendicular from the centre bisects a chord; equal chords are equidistant from the centre.","The angle at the centre is double the angle on the remaining circle."],
 [mcq("m5-1",1,"The centre of a circle through two points lies on the","perpendicular bisector of the segment joining them",["line joining them only","x-axis"],"Every point on the perpendicular bisector is equidistant from both points."),
  tf("m5-2",1,"Exactly one circle passes through three non-collinear points.",True,"This is the circumcircle."),
  tf("m5-3",1,"Of two unequal chords the longer chord is farther from the centre.",False,"The longer chord is closer to the centre."),
  num("m5-4",2,"A chord of length 8 cm is 3 cm from the centre. Radius (cm)?",5,"Half chord 4, so sqrt(16 + 9) = 5.",[(7,"Use the theorem, not addition.")]),
  num("m5-5",2,"An arc subtends 40 degrees at a point on the circle. The angle at the centre is (degrees)",80,"The central angle is double: 80.",[(20,"The central angle is double, not half.")]),
  mcq("m5-6",2,"Equal chords of a circle subtend ___ angles at the centre.","equal",["unequal","right"],"Equal chords subtend equal angles at the centre."),
  short("m5-7",3,"What is the centre of the circle through the vertices of a triangle called?",["circumcentre"],"It is the circumcentre, where the perpendicular bisectors meet."),
  mcq("m5-8",3,"A diameter of a circle is a line of symmetry. This is called","reflection symmetry",["translation","none of these"],"A circle reflects onto itself across any diameter.")])
B(6,'Perimeter and area of circles and triangles','Perimeter and area: pi, circles, sectors and Heron\'s formula','The ratio that never changes',
 "Measure the distance around any wheel and divide it by the distance across. You always get a little more than 3. That constant is pi, and it has fascinated mathematicians for centuries.",
 [("Pi is the constant ratio of the circumference to the diameter of any circle. It is about 22/7 or 3.14.","pi"),
  ("The circumference of a circle is C = 2 pi r, where r is the radius.","C = 2 pi r"),
  ("The length of an arc subtending a central angle theta is l = 2 pi r x theta / 360.","arc length"),
  ("The area of a triangle is half the base times the height.","A = 1/2 x base x height"),
  ("Heron's formula gives the area from the three sides a, b, c: area = square root of s(s - a)(s - b)(s - c), where s = (a + b + c)/2.","Heron's formula"),
  ("The area of a circle is A = pi r^2, and the area of a sector with central angle theta is pi r^2 x theta / 360.","A = pi r^2"),
  ("Many people estimated pi: Archimedes, Zu Chongzhi with 355/113, Aryabhata with 3.1416 and Madhava with an infinite series.","history of pi"),
  ("Pi is irrational, so its decimal never ends or repeats; 22/7 is only a close fraction.","pi is irrational")],
 ("Find the area of a triangle with sides 13, 14 and 15 cm.",[("s = (13 + 14 + 15)/2 = 21.","Half the perimeter."),("Area = sqrt(21 x 8 x 7 x 6) = sqrt(7056).","Apply Heron's formula."),("sqrt(7056) = 84, so the area is 84 square cm.","Take the square root.")]),
 ("What do you need for Heron's formula and why is pi special?",["All three sides and s","pi is the circumference to diameter ratio","pi is irrational"],["Using diameter in place of radius in 2 pi r"]),
 ["C = 2 pi r and A = pi r^2.","Arc length and sector area use the fraction theta/360.","Heron's formula finds a triangle's area from its sides.","Pi is irrational; 22/7 and 3.14 are approximations."],
 [mcq("m6-1",1,"The circumference of a circle of radius 7 cm (pi = 22/7) is","44 cm",["22 cm","154 cm"],"2 x 22/7 x 7 = 44."),
  mcq("m6-2",1,"The area of a circle of radius 7 cm (pi = 22/7) is","154 sq cm",["44 sq cm","49 sq cm"],"22/7 x 49 = 154."),
  tf("m6-3",1,"Pi is a rational number equal to exactly 22/7.",False,"Pi is irrational; 22/7 is only an approximation."),
  num("m6-4",2,"s for a triangle with sides 13, 14, 15",21,"(13 + 14 + 15)/2 = 21.",[(42,"42 is the perimeter; s is half of it.")]),
  num("m6-5",2,"Area (sq cm) of a triangle with sides 13, 14, 15",84,"sqrt(21 x 8 x 7 x 6) = 84.",[(21,"21 is just s.")]),
  mcq("m6-6",2,"A sector has radius 6 cm and central angle 90 degrees. Its area is (in terms of pi)","9 pi sq cm",["36 pi sq cm","18 pi sq cm"],"pi x 36 x 90/360 = 9 pi."),
  short("m6-7",3,"Who gave the approximation 355/113 for pi? (one name)",["zu chongzhi","chongzhi"],"Zu Chongzhi gave 355/113."),
  tf("m6-8",3,"The area of a triangle is half base times height.",True,"A = 1/2 x base x height.")])
B(7,'Probability basics','Probability: experiments, outcomes and tree diagrams','The mathematics of maybe',
 "Will it rain tomorrow? Will your team win the toss? Probability puts a number between 0 and 1 on how likely such events are.",
 [("Probability measures the likelihood of an event. P(E) lies between 0, which means impossible, and 1, which means certain.","0 <= P(E) <= 1"),
  ("Experimental probability is found by doing the experiment: number of times the event occurred divided by the total number of trials.","experimental probability"),
  ("Theoretical probability assumes all outcomes are equally likely: P(A) = favourable outcomes / possible outcomes.","P(A) = favourable / possible"),
  ("The sample space S is the list of all possible outcomes, for example {H, T} for a coin toss.","sample space"),
  ("An event is any outcome or group of outcomes from the sample space, such as getting an even number on a die.","event"),
  ("For a fair die, the probability of an even number is 3 out of 6, which is 1/2.","P(even) = 1/2"),
  ("A tree diagram lists all outcomes of a multi-step experiment. Two tosses of a coin give HH, HT, TH and TT.","tree diagram"),
  ("With more and more trials, the experimental probability usually comes closer to the theoretical probability.","more trials")],
 ("A bag has 3 red and 5 blue balls. Find the probability of picking a red ball.",[("Total outcomes = 3 + 5 = 8.","Count all balls."),("Favourable outcomes = 3.","Count red balls."),("P(red) = 3/8.","Divide favourable by total.")]),
 ("Explain the difference between experimental and theoretical probability.",["Experimental uses trials","Theoretical uses equally likely outcomes","Values lie between 0 and 1"],["Thinking probability can be greater than 1"]),
 ["Probability is a number from 0 to 1.","Theoretical P(A) = favourable outcomes / total outcomes.","Experimental probability uses actual trials.","Tree diagrams list outcomes of multi-step experiments."],
 [mcq("m7-1",1,"The probability of an impossible event is","0",["1","1/2"],"Impossible means no chance."),
  mcq("m7-2",1,"A fair die is rolled. P(getting 5) is","1/6",["5/6","1/5"],"One favourable outcome out of 6."),
  tf("m7-3",1,"A probability can be 1.5.",False,"Probability always lies between 0 and 1."),
  num("m7-4",2,"A coin is tossed twice. How many outcomes are in the sample space?",4,"HH, HT, TH, TT.",[(2,"Two tosses give 2 x 2 = 4 outcomes.")]),
  mcq("m7-5",2,"A bag has 3 red and 5 blue balls. P(blue) is","5/8",["3/8","5/3"],"5 blue out of 8."),
  mcq("m7-6",2,"In 50 tosses a coin shows heads 28 times. The experimental probability of heads is","28/50",["1/2","22/50"],"Times occurred / total trials."),
  short("m7-7",3,"What do we call the list of all possible outcomes?",["sample space"],"It is the sample space."),
  tf("m7-8",3,"The probability of a certain event is 1.",True,"Certain events always happen.")])
B(8,'Sequences, AP and GP','Sequences, arithmetic and geometric progressions','Predicting what comes next',
 "1, 3, 6, 10, 15 ... can you guess the next number? Spotting the rule behind a list lets you predict any term without writing them all.",
 [("A sequence is an ordered list of numbers, and each number is called a term.","sequence, term"),
  ("An explicit formula gives a term from its position n. A recursive formula gives a term from the previous terms.","explicit and recursive"),
  ("The triangular numbers 1, 3, 6, 10, 15 have nth term n(n + 1)/2, which is also the sum of the first n natural numbers.","t_n = n(n + 1)/2"),
  ("In an arithmetic progression each term is obtained by adding a fixed number d, the common difference.","AP: add d"),
  ("The nth term of an AP is t_n = a + (n - 1)d, where a is the first term.","t_n = a + (n - 1)d"),
  ("In a geometric progression each term is obtained by multiplying by a fixed number r, the common ratio.","GP: multiply by r"),
  ("The nth term of a GP is t_n = a r^(n - 1). For 2, 6, 18 the ratio is 3.","t_n = a r^(n - 1)"),
  ("Check which kind it is: subtract consecutive terms for an AP, divide them for a GP.","test: difference or ratio")],
 ("Find the 10th term of the AP 5, 8, 11, ...",[("a = 5 and d = 3.","Read the first term and the common difference."),("t_10 = 5 + 9 x 3.","Use a + (n - 1)d."),("t_10 = 32.","Simplify.")]),
 ("How do you tell an AP from a GP and find the nth term?",["AP has a common difference","GP has a common ratio","Use the correct nth term formula"],["Using n instead of n - 1"]),
 ["A sequence is an ordered list of terms.","AP: t_n = a + (n - 1)d.","GP: t_n = a r^(n - 1).","Triangular numbers have t_n = n(n + 1)/2."],
 [mcq("m8-1",1,"The common difference of 7, 11, 15, 19 is","4",["3","7"],"Each term adds 4."),
  mcq("m8-2",1,"2, 6, 18, 54 is a","geometric progression",["arithmetic progression","triangular sequence"],"Each term is multiplied by 3."),
  tf("m8-3",1,"The triangular number sequence is 1, 3, 6, 10, 15.",True,"Each term adds the next natural number."),
  num("m8-4",2,"10th term of the AP 5, 8, 11, ...",32,"5 + 9 x 3 = 32.",[(35,"Use n - 1 = 9, not 10.")]),
  num("m8-5",2,"6th triangular number",21,"6 x 7 / 2 = 21.",[(36,"Use n(n + 1)/2.")]),
  num("m8-6",2,"4th term of the GP 3, 6, 12, ...",24,"3 x 2^3 = 24.",[(48,"The exponent is n - 1 = 3.")]),
  short("m8-7",3,"The fixed number multiplied in a GP is called the common ___",["ratio"],"It is the common ratio."),
  mcq("m8-8",3,"Which formula gives the nth term of an AP?","a + (n - 1)d",["a r^(n - 1)","n(n + 1)/2"],"This is the standard AP formula.")])
